select energy_manager.load_cards($cards$[
{"id":"p1-045","paper":1,"topic":"Energy management & audit","kind":"fact","front":"What are the three phases of a detailed energy audit?","back":"Phase I: pre-audit (planning, walk-through, data collection plan). Phase II: audit (detailed measurement, analysis, energy and material balance, identifying options). Phase III: post-audit (implementing recommendations and following up on results).","explain":"Typical steps include a kick-off meeting with management, collecting historical data, preparing process flow charts, measurements, techno-economic evaluation of options, and the report with an action plan. Data collection, analysis and reporting are all steps of an audit.","flash":false,"source":"BEE 2024 P1 Q45","order":1044},
{"id":"p1-046","paper":1,"topic":"Energy management & audit","kind":"fact","front":"Which energy audit instruments measure what: Fyrite, stroboscope, sling psychrometer, Pitot tube, ultrasonic flow meter, lux meter?","back":"Fyrite: O₂ or CO₂ in flue gas. Stroboscope: rotational speed without contact. Sling psychrometer: DBT and WBT (→ RH). Pitot tube: velocity pressure in ducts (→ air velocity and flow). Ultrasonic flow meter: liquid flow (transit-time or Doppler method). Lux meter: illuminance.","explain":"A power analyser measures kW, kVA, kVAr, PF, harmonics and other quantities directly. A plain ammeter or wattmeter does not give PF on its own. Choosing the right instrument is a frequent objective question.","flash":true,"source":"BEE 2024 P1 Q6, Q46, S8; BEE 2025 P1 Q39","order":1045},
{"id":"p1-047","paper":1,"topic":"Energy management & audit","kind":"fact","front":"Define Specific Energy Consumption (SEC).","back":"SEC = Energy consumed ÷ Production in the same period, e.g. kWh/t or kcal/kg of product. Example: 5 t of coal at 4,000 kcal/kg for 25 t of cement → 20×10⁶ ÷ 25,000 kg = 800 kcal/kg.","explain":"SEC is the main plant-level energy performance indicator used for benchmarking and for PAT targets. Compare SEC only at similar capacity utilisation and product mix, because fixed energy is spread over output.","flash":false,"source":"BEE 2024 P1 Q36","order":1046},
{"id":"p1-048","paper":1,"topic":"Energy management & audit","kind":"fact","front":"How is plant energy performance calculated?","back":"Production factor = current year production ÷ reference year production. Reference year equivalent = reference year energy × production factor. Plant energy performance (%) = (reference year equivalent − current year energy) ÷ reference year equivalent × 100.","explain":"A positive value means the plant used less energy than expected for its output, so efficiency improved. A negative value means it got worse. The calculation needs current and reference year production and the reference year energy; capacity utilisation is not needed.","flash":false,"source":"BEE 2024 P1 Q4, L4","order":1047},
{"id":"p1-049","paper":1,"topic":"Energy management & audit","kind":"fact","front":"What is benchmarking in energy management?","back":"Comparing a plant's energy performance (SEC or other indicators) with its own past performance (internal) or with similar plants or best practice (external), to find improvement potential.","explain":"Fair benchmarking needs comparable boundaries, product mix, capacity utilisation, raw material quality, technology vintage and climate. PAT targets are set by benchmarking each plant's SEC against others in its sector.","flash":false,"source":"syllabus","order":1048},
{"id":"p1-050","paper":1,"topic":"Energy management & audit","kind":"fact","front":"What does a Sankey diagram show, and why is it useful?","back":"It shows energy flows through a system as arrows whose widths are proportional to the energy quantity, so inputs, useful output and losses can be seen at a glance.","explain":"Large loss streams stand out visually, which helps the energy manager prioritise where to act. It is a qualitative and quantitative presentation of an energy balance; it does not replace calculations or audits.","flash":false,"source":"BEE 2025 P1 Q38","order":1049},
{"id":"p1-051","paper":1,"topic":"Energy management & audit","kind":"problem","front":"Reference year (2023) data: production 50,000 t, energy use 30,000 toe. Current year (2024): production 55,000 t, energy use 31,500 toe. Calculate the plant energy performance for 2024 and interpret it.","back":"Plant energy performance = +4.55%, so the plant used 4.55% less energy than expected for its production (an improvement).","explain":"The production factor scales reference-year energy to what the plant would have used at this year's output. A positive result means the plant performed better than the reference year. A negative result, as in the BEE 2024 question (−5.56%), means performance got worse.","steps":[{"prompt":"Calculate the production factor.","answer":"PF = 55,000 ÷ 50,000 = 1.10","explain":"PF = current year production ÷ reference year production."},{"prompt":"Calculate the reference year equivalent energy.","answer":"30,000 × 1.10 = 33,000 toe","explain":"Expected energy at current output = reference energy × PF."},{"prompt":"Calculate plant energy performance.","answer":"(33,000 − 31,500) ÷ 33,000 × 100 = +4.55%","explain":"PEP = (Ref. eq. − Current energy) ÷ Ref. eq. × 100."},{"prompt":"Interpret the result.","answer":"Positive value: the plant saved 1,500 toe compared with expected consumption.","explain":"A negative value would mean worse performance."}],"flash":false,"source":"BEE 2024 P1 L4(b) (modified)","order":1050},
{"id":"p1-052","paper":1,"topic":"Material & energy balance","kind":"fact","front":"What principle underlies material and energy balances?","back":"Conservation of mass and energy: Input = Output + Accumulation (stored) + Losses. At steady state with nothing stored, Input = Output.","explain":"Example: 1,000 kg/h raw material in, with 700 kg product, 200 kg waste and 50 kg stored out → unaccounted loss = 1,000 − 950 = 50 kg/h. Draw a boundary around the process, list every stream crossing it, and balance one component (e.g. solids or fat) at a time.","flash":true,"source":"BEE 2025 P1 Q4, Q5","order":1051},
{"id":"p1-053","paper":1,"topic":"Material & energy balance","kind":"fact","front":"In concentration and drying problems, what quantity is the 'tie element' for the material balance?","back":"The non-volatile component (dissolved solids, bone-dry solids or fat), whose mass is the same in feed and product. Example: 100 kg of feed at 6% solids → 6 kg solids → product at 30% = 20 kg, so water evaporated = 80 kg.","explain":"Balance the conserved component first to get the product mass, then find the water removed by difference. Moisture on a wet basis = water ÷ (water + solids). The same logic gives salt concentration: 25 kg salt in 100 kg water = 25/125 = 20% by weight.","flash":false,"source":"BEE 2025 P1 Q11; BEE 2024 P1 Q37","order":1052},
{"id":"p1-054","paper":1,"topic":"Material & energy balance","kind":"fact","front":"In an energy balance, how is equipment efficiency calculated by the direct method?","back":"Efficiency = useful energy output ÷ energy input × 100. Example: boiler with 100 MJ fuel input and 70 MJ in steam → 70%. The losses (flue gas 20 MJ + radiation/unaccounted 10 MJ) make up the other 30 MJ.","explain":"In the indirect (loss) method, efficiency = 100 − Σ losses %. A complete energy balance must close: input = useful output + all losses. A large unaccounted figure points to measurement errors or a missed stream.","flash":false,"source":"BEE 2025 P1 Q5","order":1053},
{"id":"p1-055","paper":1,"topic":"Material & energy balance","kind":"problem","front":"A dryer receives 2,000 kg/h of wet material at 40% moisture (wet basis) and dries it to 5% moisture (wet basis). Latent heat of evaporation is 540 kcal/kg. Ignore the sensible heat of the solids. Find (a) the product rate, (b) the water evaporated, (c) the heat needed for evaporation, and (d) the steam needed if steam gives 520 kcal/kg and the dryer thermal efficiency is 60%.","back":"(a) 1,263.2 kg/h; (b) 736.8 kg/h; (c) ≈ 3.98 lakh kcal/h; (d) ≈ 1,275 kg/h of steam.","explain":"Bone-dry solids pass through unchanged, so they tie the feed and product together. The water removed is the difference between the feed and product masses. Heat for evaporation is then divided by the useful heat delivered per kg of steam.","steps":[{"prompt":"Find the bone-dry solids.","answer":"2,000 × (1 − 0.40) = 1,200 kg/h","explain":"Solids fraction = 1 − moisture (wet basis)."},{"prompt":"Find the product mass at 5% moisture.","answer":"Product = 1,200 ÷ 0.95 = 1,263.2 kg/h","explain":"Solids are 95% of the product."},{"prompt":"Find the water evaporated.","answer":"2,000 − 1,263.2 = 736.8 kg/h","explain":"Mass balance: feed = product + vapour."},{"prompt":"Find the heat for evaporation.","answer":"736.8 × 540 = 3,97,895 kcal/h","explain":"Q = m × latent heat."},{"prompt":"Find the steam required.","answer":"3,97,895 ÷ (0.60 × 520) = 1,275 kg/h","explain":"Steam = heat needed ÷ (efficiency × heat per kg of steam)."}],"flash":false,"source":"BEE 2025 P1 S7 (modified)","order":1054},
{"id":"p1-056","paper":1,"topic":"Material & energy balance","kind":"problem","front":"An evaporator is fed 4,000 kg/h of solution containing 2% solids, which is concentrated to 8% solids. Enthalpies: feed 40 kcal/kg, concentrated product 100 kcal/kg, vapour 640 kcal/kg. The heating steam gives up 540 kcal/kg (its condensate leaves at saturation). Find the vapour formed and the steam required per hour, and the steam economy.","back":"Vapour = 3,000 kg/h; steam ≈ 3,444 kg/h; steam economy ≈ 0.87 kg vapour per kg steam.","explain":"The solids balance gives the product and vapour flows. The heat balance (heat from steam + heat in feed = heat in vapour + heat in product) gives the steam needed. A single-effect evaporator has a steam economy below 1; multiple effects raise it.","steps":[{"prompt":"Solids balance to find the product.","answer":"Solids = 4,000 × 0.02 = 80 kg/h; product = 80 ÷ 0.08 = 1,000 kg/h","explain":"Solids in = solids out."},{"prompt":"Find the vapour formed.","answer":"4,000 − 1,000 = 3,000 kg/h","explain":"Feed = product + vapour."},{"prompt":"Write the heat balance.","answer":"Steam heat + 4,000×40 = 3,000×640 + 1,000×100 → Steam heat = 19,20,000 + 1,00,000 − 1,60,000 = 18,60,000 kcal/h","explain":"Heat in = heat out."},{"prompt":"Find the steam required.","answer":"18,60,000 ÷ 540 = 3,444 kg/h","explain":"Steam = heat ÷ heat given per kg of steam."},{"prompt":"Find the steam economy.","answer":"3,000 ÷ 3,444 = 0.87","explain":"Economy = kg vapour ÷ kg steam."}],"flash":false,"source":"BEE 2024 P1 L6 (modified)","order":1055},
{"id":"p1-057","paper":1,"topic":"Energy action planning","kind":"fact","front":"What is the first step in an energy action plan?","back":"Getting top management commitment, usually by forming an energy management cell and appointing an energy manager, with the backing of a written energy policy.","explain":"BEE's sequence is: make a commitment, assess performance and opportunities, set goals and targets, create an action plan, implement it, evaluate progress, and recognise achievements. Without management backing, resources and authority for projects never arrive.","flash":true,"source":"BEE 2025 P1 Q9","order":1056},
{"id":"p1-058","paper":1,"topic":"Energy action planning","kind":"fact","front":"What is force field analysis in energy action planning, and which approach is usually more effective?","back":"It lists the positive (driving) and negative (restraining) forces acting on a goal. Minimising the negative forces (barriers) is usually more effective than strengthening the positive ones.","explain":"Pushing harder on driving forces tends to provoke more resistance. Removing barriers such as lack of funds, skills or ownership lets change happen with less friction. The analysis is used when planning energy-saving changes in an organisation.","flash":false,"source":"BEE 2024 P1 Q13; BEE 2025 P1 Q12","order":1057},
{"id":"p1-059","paper":1,"topic":"Energy action planning","kind":"fact","front":"What are the essential elements of a written energy policy?","back":"A statement of management commitment, clear objectives and targets for energy performance, responsibilities and accountability (energy manager or cell), allocation of resources, and a commitment to monitor, report and continually improve.","explain":"The policy is signed by top management and communicated to all staff. Under ISO 50001 it must also commit to legal compliance and to supporting procurement of efficient products and design for energy performance.","flash":false,"source":"syllabus","order":1058},
{"id":"p1-060","paper":1,"topic":"Energy action planning","kind":"fact","front":"Why is an Energy Management System (EnMS) such as ISO 50001 adopted?","back":"To manage energy use systematically through a Plan-Do-Check-Act cycle (policy, baseline, EnPIs, objectives and targets, action plans, monitoring, review), so that energy performance improves continually.","explain":"Cost savings and efficiency follow from the system, but the defining reason is systematic management rather than one-off projects. Key ISO 50001 terms: energy review, significant energy uses (SEUs), energy baseline (EnB) and energy performance indicators (EnPIs).","flash":false,"source":"BEE 2024 P1 Q28, L3","order":1059},
{"id":"p1-061","paper":1,"topic":"Energy action planning","kind":"fact","front":"In Total Productive Maintenance (TPM), what are the 'six big losses'?","back":"Breakdowns, setup and adjustment losses, idling and minor stoppages, reduced speed, process defects, and reduced yield at start-up. Excessive overtime is NOT one of them.","explain":"The six losses fall into three groups: availability (breakdowns, setup), performance (minor stops, reduced speed) and quality (defects, start-up yield). Overall Equipment Effectiveness (OEE) = Availability × Performance × Quality.","flash":false,"source":"BEE 2025 P1 Q16","order":1060},
{"id":"p1-062","paper":1,"topic":"Financial management","kind":"fact","front":"What is simple payback period and what are its limitations?","back":"Simple payback = First cost (investment) ÷ Net annual cash savings. It does not account for the time value of money or for savings after the payback period.","explain":"It is quick and easy to understand, which makes it useful for screening low-cost energy measures. Two projects with the same payback can have very different lifetime value, so use NPV or IRR for larger investments.","flash":false,"source":"BEE 2024 P1 Q47","order":1061},
{"id":"p1-063","paper":1,"topic":"Financial management","kind":"fact","front":"How is Return on Investment (ROI) calculated?","back":"ROI (%) = Annual net cash flow ÷ Capital cost × 100. Example: ₹20,000 per year on ₹1,00,000 → 20%.","explain":"ROI is the reciprocal of simple payback (×100). Like payback, it ignores the time value of money. For a project to be worthwhile, ROI should exceed the interest rate on borrowed money or the cost of capital.","flash":false,"source":"BEE 2025 P1 Q48","order":1062},
{"id":"p1-064","paper":1,"topic":"Financial management","kind":"fact","front":"Define Net Present Value (NPV).","back":"NPV = Σ CFₜ ÷ (1 + i)ᵗ for t = 0 to n, the sum of all cash flows discounted to today at the discount rate i, with the investment entered as a negative cash flow at t = 0. Accept the project if NPV > 0.","explain":"The present value factor 1/(1+i)ᵗ converts future savings into today's money. NPV tells you how much value the project adds beyond the required return. Among mutually exclusive projects with no capital limit, choose the highest NPV.","flash":false,"source":"BEE 2024 P1 Q49","order":1063},
{"id":"p1-065","paper":1,"topic":"Financial management","kind":"fact","front":"Define Internal Rate of Return (IRR).","back":"IRR is the discount rate at which the NPV of a project's cash flows equals zero. Accept the project if IRR > cost of capital.","explain":"IRR is found by trial and interpolation: IRR = r₁ + NPV₁ × (r₂ − r₁) ÷ (NPV₁ − NPV₂), where NPV₁ > 0 at the lower rate r₁ and NPV₂ < 0 at r₂. Both NPV and IRR account for the time value of money; simple payback and ROI do not.","flash":true,"source":"BEE 2024 P1 Q5, Q18","order":1064},
{"id":"p1-066","paper":1,"topic":"Financial management","kind":"fact","front":"Two projects of equal life: X has IRR 40%, NPV ₹50,000; Y has IRR 30%, NPV ₹1,20,000. With no capital limit, which do you choose?","back":"Project Y, because it has the higher NPV.","explain":"When NPV and IRR rankings conflict for mutually exclusive projects and funds are not limited, NPV is preferred: it measures the absolute value added. IRR is a percentage and favours small projects, and it assumes cash is reinvested at the IRR.","flash":false,"source":"BEE 2025 P1 Q14; BEE 2024 P1 L3","order":1065},
{"id":"p1-067","paper":1,"topic":"Financial management","kind":"fact","front":"What do these terms mean: net operating cash inflow, economic life, salvage value, depreciation?","back":"Net operating cash inflow: annual savings minus operating and maintenance costs (after tax where applicable). Economic life: the period over which the project gives useful savings. Salvage value: what the asset can be sold for at the end of its life (a cash inflow in the final year). Depreciation: the decrease in an asset's value over time.","explain":"Depreciation is not a cash outflow, but it lowers taxable profit and so affects after-tax cash flows. Include salvage in the last year's cash flow and any mid-life reinvestment in the year it happens.","flash":false,"source":"BEE 2024 P1 L3; BEE 2025 P1 Q15","order":1066},
{"id":"p1-068","paper":1,"topic":"Financial management","kind":"fact","front":"What is sensitivity analysis in project financial evaluation?","back":"Testing how NPV, IRR or payback change when key assumptions change: energy price, fuel cost, savings achieved, capital cost, project life, discount rate, or tax rate (a macro factor).","explain":"It shows which variables the project's viability depends on most, and how robust the decision is. Energy price escalation and the level of savings achieved are usually the most influential variables in energy projects.","flash":false,"source":"BEE 2024 P1 Q31","order":1067},
{"id":"p1-069","paper":1,"topic":"Financial management","kind":"fact","front":"What are the options for financing energy efficiency projects?","back":"Debt financing (loans), equity, retained earnings (internal funds), capital lease, true (operating) lease, and performance contracting through ESCOs.","explain":"In performance contracting, the ESCO's payment is tied to the energy savings achieved, which lowers the client's risk. A stock buyback is not a financing option. Public schemes such as EEFP under NMEEE help channel finance to energy efficiency.","flash":false,"source":"BEE 2024 P1 Q48; BEE 2025 P1 Q13, L4","order":1068},
{"id":"p1-070","paper":1,"topic":"Financial management","kind":"fact","front":"How do 'guaranteed savings' and 'shared savings' ESCO contracts differ?","back":"Guaranteed savings: the client arranges the finance, and the ESCO designs and implements the project and guarantees a level of savings. Shared savings: the ESCO finances the project and is repaid from an agreed share of the savings.","explain":"In guaranteed savings, the ESCO carries the performance risk and the client carries the credit risk. In shared savings, the ESCO carries both. Measurement & Verification (M&V) checks that the guaranteed or shared savings were actually achieved.","flash":false,"source":"BEE 2025 P1 Q33, Q47","order":1069},
{"id":"p1-071","paper":1,"topic":"Financial management","kind":"fact","front":"Why is life-cycle costing better than comparing purchase prices?","back":"It includes the operating (energy), maintenance and disposal costs over the asset's whole life, not just the first cost.","explain":"For motors, pumps and compressors, energy cost over the life can be many times the purchase price. A cheaper but inefficient unit can therefore cost far more in total.","flash":false,"source":"BEE 2025 P1 Q20","order":1070},
{"id":"p1-072","paper":1,"topic":"Financial management","kind":"problem","front":"A 37 kW pump motor runs at 70% load with 90% efficiency for 20 h/day, 330 days/year. A VFD costing ₹2,50,000 is expected to cut its energy use by 15%. Power costs ₹8/kWh. Find the annual energy use, savings, simple payback and ROI.","back":"Energy ≈ 1,89,933 kWh/yr; savings ≈ 28,490 kWh = ₹2,27,920/yr; payback ≈ 1.1 years (~13 months); ROI ≈ 91%.","explain":"Input power = rated output × load ÷ efficiency. Savings are a percentage of current consumption. Payback and ROI are reciprocals; a payback near one year makes this an attractive low-risk measure.","steps":[{"prompt":"Find the motor input power.","answer":"37 × 0.70 ÷ 0.90 = 28.78 kW","explain":"Input = output × loading ÷ efficiency."},{"prompt":"Find the annual energy use.","answer":"28.78 × 20 × 330 = 1,89,933 kWh/yr","explain":"Energy = power × operating hours (6,600 h)."},{"prompt":"Find the energy and cost savings.","answer":"1,89,933 × 0.15 = 28,490 kWh; × ₹8 = ₹2,27,920/yr","explain":"Savings = % reduction × energy × tariff."},{"prompt":"Find the simple payback.","answer":"2,50,000 ÷ 2,27,920 = 1.10 years","explain":"Payback = investment ÷ annual savings."},{"prompt":"Find the ROI.","answer":"2,27,920 ÷ 2,50,000 × 100 = 91.2%","explain":"ROI = annual savings ÷ investment × 100."}],"flash":false,"source":"BEE 2025 P1 S6 (modified)","order":1071},
{"id":"p1-073","paper":1,"topic":"Financial management","kind":"problem","front":"Two mutually exclusive projects each have a 5-year life. Project A costs ₹5 lakh and saves ₹1.6 lakh/yr. Project B costs ₹9 lakh and saves ₹2.75 lakh/yr. At a 12% discount rate, compare them by simple payback and by NPV. Which should be chosen if funds are not limited?","back":"Payback: A 3.13 yr, B 3.27 yr. NPV: A ≈ ₹0.77 lakh, B ≈ ₹0.91 lakh. Choose B (higher NPV).","explain":"Simple payback favours A, but payback ignores the time value of money and the absolute value created. NPV shows that B adds more wealth. With no capital constraint, NPV decides.","steps":[{"prompt":"Compute the simple paybacks.","answer":"A: 5 ÷ 1.6 = 3.13 yr; B: 9 ÷ 2.75 = 3.27 yr","explain":"Payback = cost ÷ annual savings."},{"prompt":"Find the cumulative PV factor at 12% for 5 years.","answer":"1/1.12 + 1/1.12² + … + 1/1.12⁵ = 0.893+0.797+0.712+0.636+0.567 = 3.605","explain":"Uniform annual savings: PV = savings × Σ 1/(1+i)ᵗ."},{"prompt":"Compute NPV of A.","answer":"1.6 × 3.605 − 5 = 5.768 − 5 = ₹0.77 lakh","explain":"NPV = PV of inflows − investment."},{"prompt":"Compute NPV of B.","answer":"2.75 × 3.605 − 9 = 9.913 − 9 = ₹0.91 lakh","explain":""},{"prompt":"Decide.","answer":"NPV(B) > NPV(A), so choose B, even though its payback is longer.","explain":"With no capital limit, select the project with the higher NPV."}],"flash":false,"source":"BEE 2025 P1 L5 (modified)","order":1072},
{"id":"p1-074","paper":1,"topic":"Financial management","kind":"problem","front":"An energy-efficiency project costs ₹10 lakh and gives net savings of ₹3 lakh per year for 5 years, with no salvage value. Find the IRR by interpolation between 15% and 16%.","back":"IRR ≈ 15.24%.","explain":"IRR is the rate at which NPV = 0. Calculate NPV at two rates either side of zero and interpolate linearly. If the company's cost of capital is below 15.24%, the project is acceptable.","steps":[{"prompt":"NPV at 15%.","answer":"PV factor sum (5 yr, 15%) = 3.3522; NPV = 3 × 3.3522 − 10 = +₹0.0565 lakh","explain":"NPV = Σ CF/(1+r)ᵗ − investment."},{"prompt":"NPV at 16%.","answer":"PV factor sum (5 yr, 16%) = 3.2743; NPV = 3 × 3.2743 − 10 = −₹0.1771 lakh","explain":"The sign has changed, so the IRR lies between 15% and 16%."},{"prompt":"Interpolate.","answer":"IRR = 15 + 0.0565 × (16 − 15) ÷ (0.0565 + 0.1771) = 15 + 0.24 = 15.24%","explain":"IRR = r₁ + NPV₁ (r₂ − r₁) ÷ (NPV₁ − NPV₂)."},{"prompt":"Decide.","answer":"Accept if the cost of capital is below 15.24%.","explain":"IRR > cost of capital → project adds value."}],"flash":false,"source":"BEE 2024 P1 L2, S4 (modified)","order":1073},
{"id":"p1-075","paper":1,"topic":"Project management","kind":"fact","front":"What is a Work Breakdown Structure (WBS)?","back":"A hierarchical breakdown of a complex project into smaller, manageable tasks or work packages that can be scheduled, costed and assigned.","explain":"The WBS is the basis for estimating time and cost and for building network diagrams. The lowest level should be a work package that one person or team can own.","flash":false,"source":"BEE 2025 P1 Q22","order":1074},
{"id":"p1-076","paper":1,"topic":"Project management","kind":"fact","front":"What is the main limitation of a Gantt chart?","back":"It does not clearly show logical dependencies between activities, so it cannot identify the critical path.","explain":"Gantt (bar) charts show each activity's start, duration and finish against a calendar, which makes them good for communicating progress. Network methods (CPM/PERT) are needed to analyse dependencies and float.","flash":false,"source":"BEE 2025 P1 Q23","order":1075},
{"id":"p1-077","paper":1,"topic":"Project management","kind":"fact","front":"How does CPM differ from PERT?","back":"CPM is deterministic: each activity has one fixed duration, and the method is often used for time-cost trade-offs. PERT is probabilistic: it uses three time estimates per activity, te = (a + 4m + b) ÷ 6, with variance ((b − a)/6)².","explain":"PERT suits R&D or new projects where durations are uncertain. It gives the probability of finishing by a target date. CPM suits repetitive projects such as construction where durations are well known. Both identify the critical path.","flash":false,"source":"BEE 2025 P1 Q27, S3","order":1076},
{"id":"p1-078","paper":1,"topic":"Project management","kind":"fact","front":"What is the critical path, and which common statement about it is false?","back":"The critical path is the longest-duration path through the network. Its length is the minimum time needed to complete the project, and its activities have zero float. False statement: 'it is the maximum time required to complete the project'.","explain":"Any delay to a critical activity delays the whole project, so management attention goes there. There can be more than one critical path, and the critical path can shift as activities progress.","flash":false,"source":"BEE 2024 P1 Q15","order":1077},
{"id":"p1-079","paper":1,"topic":"Project management","kind":"fact","front":"How is slack (float) of an activity calculated? Is an activity with ES = 8 and LS = 10 critical?","back":"Slack = LS − ES = LF − EF. Here slack = 10 − 8 = 2 days, so the activity is NOT critical (critical activities have zero slack).","explain":"Example: LS = 8, LF = 12, EF = 9 → slack = LF − EF = 12 − 9 = 3 weeks. The forward pass gives ES/EF (take the maximum of predecessors' EF); the backward pass gives LS/LF (take the minimum of successors' LS).","flash":false,"source":"BEE 2024 P1 Q17; BEE 2025 P1 Q28, Q30","order":1078},
{"id":"p1-080","paper":1,"topic":"Project management","kind":"fact","front":"Why is a dummy activity used in a project network (activity-on-arrow) diagram?","back":"To show a logical dependency, or to keep two activities that share the same start and end nodes distinct. A dummy has zero duration and uses no resources.","explain":"Dummies are drawn as dashed arrows. They only preserve correct precedence logic; they do not change the project duration.","flash":false,"source":"BEE 2025 P1 Q24","order":1079},
{"id":"p1-081","paper":1,"topic":"Project management","kind":"problem","front":"Activities (duration in weeks; predecessors): A 4 (–), B 6 (–), C 3 (A), D 5 (A), E 4 (B, C), F 2 (D, E). Find ES, EF, LS, LF and slack for each activity, the critical path, and the project duration.","back":"Critical path A–C–E–F, duration 13 weeks. Slack: B = 1 week, D = 2 weeks; all others 0.","explain":"The forward pass gives the earliest times (take the maximum EF of predecessors). The backward pass from the project end gives the latest times (take the minimum LS of successors). Activities with zero slack form the critical path, the longest path through the network.","steps":[{"prompt":"Forward pass for A, B, C, D.","answer":"A: ES 0, EF 4; B: ES 0, EF 6; C: ES 4, EF 7; D: ES 4, EF 9","explain":"EF = ES + duration; ES = maximum EF of predecessors."},{"prompt":"Forward pass for E and F.","answer":"E: ES = max(6, 7) = 7, EF 11; F: ES = max(9, 11) = 11, EF 13 → project = 13 weeks","explain":"Project duration = EF of the last activity."},{"prompt":"Backward pass.","answer":"F: LF 13, LS 11; E: LF 11, LS 7; D: LF 11, LS 6; C: LF 7, LS 4; B: LF 7, LS 1; A: LF = min(4, 6) = 4, LS 0","explain":"LS = LF − duration; LF = minimum LS of successors."},{"prompt":"Find slack and the critical path.","answer":"Slack (LS − ES): A 0, B 1, C 0, D 2, E 0, F 0 → critical path A–C–E–F = 4+3+4+2 = 13 weeks","explain":"Zero-slack activities are critical."}],"flash":false,"source":"BEE 2025 P1 L1; BEE 2024 P1 L5 (modified)","order":1080}
]$cards$::jsonb);
